app.controller("QuizFormCtrl",["$scope","$http","$filter",function(n,t){var i=this;i.enableSubmit=!1;i.get_quiz_result_url="";i.quiz={quiz_name:"",time_limit:null,begin_timestamp:null,questions:[]};n.loading=!1;i.init=function(t,r){n.loading=!0;i.quiz=t;i.get_quiz_result_url=r;i.quiz.questions.forEach(function(n){if(n.selected=null,n.choices=n.choices||[],n.idx=n.idx||idx++,n.hasAnswer=!1,typeof n.choices=="string")try{n.choices=JSON.parse(n.choices)}catch(t){}});i.quiz.total_questions=i.quiz.questions.length;i.quiz.correct_answers=0;i.quiz.score=0;i.submitted=!1;i.quiz.begin_timestamp=moment(new Date).format("YYYY-MM-DDTHH:mm:ss");i.getQuizResult()};i.getQuizResult=function(){t.get(i.get_quiz_result_url).then(function(t){var r=t.data.response;r.answers_detail&&i.quiz&&i.quiz.questions&&(i.quiz.total_questions=r.total_questions,i.quiz.correct_answers=r.correct_answers,i.quiz.score=r.score,i.quiz.submitted=!0,i.quiz.begin_timestamp=new Date(r.begin_timestamp),i.quiz.end_timestamp=new Date(r.end_timestamp),i.quiz.questions.forEach(function(n){let t=r.answers_detail.find(t=>t.question_id===n.id);t&&(n.hasAnswer=!0,n.selected=t.selected_choice_index,n.correct_answer_index=t.correct_answer_index,n.is_correct=t.is_correct)}));n.loading=!1;i.enableSubmit=!1;n.$applyAsync()}).catch(function(t){i.enableSubmit=!0;n.loading=!1;n.$applyAsync();console.error(t)})};i.submitAnswers=function(n){var t='<div class="alert  p-2" role="alert">{0}<\/div>'.format(JSR.did_you_finish_this_quiz);toastr.confirm(t,function(){i.confirmSubmitAnswers(n)},null)};i.confirmSubmitAnswers=function(r){let u=i.quiz.questions.filter(n=>n.selected===undefined||n.selected===null);if(u.length>0){toastr.warning(JSR.must_response_before_submit,"",{timeOut:5e3});return}let f=i.quiz.questions.map(function(n){return{question_id:n.id,selected_choice_index:n.selected}});var e=moment(new Date).format("YYYY-MM-DDTHH:mm:ss");let o={quiz_id:i.quiz.id,begin_timestamp:i.quiz.begin_timestamp,end_timestamp:e,answers:f};n.loading=!0;t.post(r,o).then(function(t){n.loading=!1;var r=t.data.response,u='<div class="alert alert-success p-2" role="alert">{0}<\/div>'.format(JSR.quiz_submitted_successfully),f='<div class="p-1 text-center">{0} : <b class="text-lg">{1}%<\/b><hr/>{2} : <b  class="text-lg">{3}/{4}<\/b><\/div>'.format(JSR.correct,r.score,JSR.score,r.correct_answers,r.total_questions);toastr.success(u+f,"",{timeOut:2e5});i.getQuizResult()}).catch(function(t){n.loading=!1;(t.status==400||t.status==403)&&toastr.error(t.data.error,"",{timeOut:3e3});console.error(t)})};i.getFeedbackMessage=function(n){if(!n||n.total_questions===0)return"Aucun résultat disponible.";var t=n.correct_answers/n.total_questions*100;return t===100?JSR.quiz_score_100:t>=80?JSR.quiz_score_80:t>=60?JSR.quiz_score_60:t>=40?JSR.quiz_score_40:t>=20?JSR.quiz_score_20:JSR.quiz_score_inf_20};i.getDuration=function(n,t){if(n&&t){const e=new Date(n),o=new Date(t),s=o-e,i=Math.floor(s/1e3),r=Math.floor(i/3600),u=Math.floor(i%3600/60),f=i%60;return r>0?`${r}h ${u}mn ${f}s`:`${u}mn ${f}s`}return""}}]);